// Задача 1. Знакомство с монитором порта
// Каждую секунду выводим время работы платы.

unsigned long lastPrintedSecond = 0;

void setup() {
  Serial.begin(9600);
  Serial.println("Arduino готов к работе!");
}

void loop() {
  unsigned long currentSecond = millis() / 1000UL;

  if (currentSecond != lastPrintedSecond) {
    lastPrintedSecond = currentSecond;
    Serial.print("Секунда: ");
    Serial.println(currentSecond);
  }
}
